const node=(tag:string,label?:string,cls?:string)=>{const el=document.createElement(tag);if(label!==undefined)el.textContent=label;if(cls)el.className=cls;return el;};

const action=(label:string,fn:()=>any,cls?:string)=>{const b=node('button',label,cls) as HTMLButtonElement;b.onclick=()=>void perform(fn);return b;};

async function request(action:string,data?:any){const r=await window.proteonator.request(action,data);if(!r.ok)throw new Error(r.error);if(r.notice){let notice=document.getElementById('preference-notice');if(!notice){notice=node('div',undefined,'preference-notice');notice.id='preference-notice';notice.setAttribute('role','status');document.querySelector('footer')!.before(notice);}const dismiss=document.createElement('button');dismiss.textContent='Dismiss';dismiss.onclick=()=>notice!.remove();notice.replaceChildren(node('span',r.notice),dismiss);}return r.value;}

async function digest(t:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t)))).map(x=>x.toString(16).padStart(2,'0')).join('');}

