const readOnlyCommands=new Set(['cancel','fit','focus','job-history','commands','methods','navigation-back','navigation-forward']);
function lockTaskEdits(){const locked=new Map<HTMLInputElement|HTMLButtonElement|HTMLSelectElement|HTMLTextAreaElement,boolean>();const update=()=>{for(const [element]of locked)if(!element.isConnected)locked.delete(element);for(const element of document.querySelectorAll<HTMLInputElement|HTMLButtonElement|HTMLSelectElement|HTMLTextAreaElement>('header button,.ribbon button,.ribbon input,.ribbon select,.workspace-tabs button,.objects button,.objects input,.objects select,.inspector button,.inspector input,.inspector textarea,.inspector select,.results button,.results input,.scene-actions button,.scene-actions input,#sequence-workspace button,#sequence-workspace input,#sequence-workspace textarea,#sequence-workspace select')){if(element.matches('[data-tab],[data-workspace],[data-sequence-tab],.state-choice,[data-protein-position],#residue-search,#sequence-chain,.atom')||readOnlyCommands.has(element.dataset.command??''))continue;if(!locked.has(element)){locked.set(element,element.disabled);element.disabled=true;}}};update();const observer=new MutationObserver(update);observer.observe(document.body,{childList:true,subtree:true});return ()=>{observer.disconnect();for(const [element,disabled]of locked)if(element.isConnected)element.disabled=disabled;};}
async function task<T>(label:string,fn:()=>Promise<T>):Promise<T>{if(busy)throw new Error('Wait for the current operation or cancel it.');const record={id:crypto.randomUUID(),label,inputState:sequenceMode?(sequenceWorkbench?.activeState()?.name??'Sequence workspace'):(currentScenario()?.title??'Source'),inputHash:currentScenario()?.result?.hash??source?.sha256??null,status:'running',startedAt:new Date().toISOString()} as typeof jobRecords[number];jobRecords.push(record);if(jobRecords.length>50)jobRecords.shift();const focus=document.activeElement as HTMLElement;busy=true;jobId=crypto.randomUUID();const unlockEdits=lockTaskEdits();$('cancel').hidden=false;$('cancel').focus();notify(label);try{if(sequenceMode&&sequenceWorkbench?.activeState())record.inputHash=await digest(JSON.stringify(sequenceWorkbench.activeState()));const result=await fn();record.status='completed';return result;}catch(error:any){record.status=/cancel/i.test(error.message)?'cancelled':'failed';record.error=error.message;throw error;}finally{record.finishedAt=new Date().toISOString();busy=false;if((document.getElementById('job-history') as HTMLDialogElement|null)?.open)showJobs();if(pendingStartupOpen){pendingStartupOpen=false;setTimeout(()=>void perform(()=>runCommand('open-startup-project')),0);}$('cancel').hidden=true;unlockEdits();if(focus?.isConnected)focus.focus({preventScroll:true});}}

const inspectionCache=new Map<string,Inspection>();

async function compute(operation:string,data:any){if(operation==='measure')return measurePositions(data.positions);if(operation!=='inspect'){const record=jobRecords.findLast(r=>r.status==='running');if(record){const settings=Object.fromEntries(Object.entries(data).filter(([key,value])=>!['text','baseline','variant','baselineText','reference','mobile','topologyText','data','positions'].includes(key)&&(typeof value==='number'||typeof value==='boolean'||typeof value==='string'&&value.length<1024||key==='settings'||key==='edits'||key==='residues')));record.methods??=[];record.methods.push({operation,requestSha256:await digest(JSON.stringify({operation,...data})),settings:structuredClone(settings)});record.methods=record.methods.slice(-32);}return request('compute',{operation,jobId,...data});}const key=await digest(JSON.stringify(data));const cached=inspectionCache.get(key);if(cached){inspectionCache.delete(key);inspectionCache.set(key,cached);return cached;}const result=await request('compute',{operation,jobId,...data});if(result.atoms.length<30000){inspectionCache.set(key,result);while(inspectionCache.size>4)inspectionCache.delete(inspectionCache.keys().next().value!);}return result;}

