async function isolateSelection(ids:string[]|null,mode:'isolate'|'dim'='isolate'){isolationMode=mode;if(!viewer||!sceneRoots[0])throw new Error('Open coordinates first.');if(isolationComponent&&viewer.plugin.state.data.cells.has(isolationComponent.ref))await viewer.plugin.build().delete(isolationComponent).commit();isolationComponent=null;isolatedIds=ids;for(const c of components.filter(c=>c.viewer===viewer))c.viewer.setVisibility(c.ref.ref,ids&&mode==='isolate'?true:(displayState[c.key]?.hidden??(c.kind==='water'&&!val('show-water').checked)));if(ids){const parent=[...viewer.plugin.state.data.cells.values()].find((cell:any)=>cell.obj?.data===sceneRoots[0]) as any;if(!parent)throw new Error('Displayed structure is unavailable.');const S=window.molstar.lib.structure.StructureElement.Schema;const items=currentInspection!.residues.filter(r=>ids.includes(r.id)).map(r=>elementSchema(r));isolationComponent=await viewer.plugin.builders.structure.tryCreateComponentFromExpression(parent.transform.ref,S.toExpression({items}),'isolated-selection',{label:'Isolated selection'});if(isolationComponent)await viewer.plugin.builders.structure.representation.addRepresentation(isolationComponent,{type:'ball-and-stick',color:'element-symbol'});}await updateDisplay();markDirty();}

async function typedInteractions(show:boolean){showTypedInteractions=show;if(interactionLayer&&viewer.plugin.state.data.cells.has(interactionLayer.ref))await viewer.plugin.build().delete(interactionLayer).commit();interactionLayer=null;if(!show||!sceneRoots[0])return null;if(currentInspection!.atoms.length>30000)throw new Error('Typed interactions are limited to 30,000 atoms.');const parent=[...viewer.plugin.state.data.cells.values()].find((cell:any)=>cell.obj?.data===sceneRoots[0]) as any;if(!parent)throw new Error('Molecular root is unavailable.');interactionParams=await viewer.prepareInteractions(sceneRoots[0]);interactionLayer=await viewer.plugin.builders.structure.representation.addRepresentation(parent.transform.ref,{type:'interactions',color:'interaction-type'});return interactionParams;}
