 sequencePage=Math.min(Math.max(0,sequencePage),Math.max(0,Math.ceil(all.length/300)-1));const key=[currentInspection?.sourceSha256,chain,query,sequencePage,currentScenario()?.edits.map(e=>e.residue+e.modification).join('|')].join('/'),selected=new Set(selectionResidues);

