 viewer?.structureInteractivity({elements:{items:selectionResidues.map(id=>elementSchema(currentInspection!.residues.find(r=>r.id===id)!)).filter(Boolean)},action:focus?['select','focus']:'select',applyGranularity:false});renderNotes();

 updateChemistry();const mapped=context?.mapping?findMapping(r):null;text('feature-track',mapped??`${r.name} ${r.id} · structural numbering${currentScenario()?.edits.some(e=>e.residue===id)?' · chemically edited':''}`);

