async function applyPtm(){tab('ptm');if(!source)throw new Error('Open coordinates first.');const checks=ptmPreflight(selectionResidues.length?selectionResidues:[selectedResidue],sel('modification').value),eligible=checks.filter(c=>c.eligible);if(!eligible.length)throw new Error(checks.map(c=>c.id+': '+c.reason).join('; '));if(eligible.length>32)throw new Error('A scenario supports at most 32 edited residues. Narrow the reviewed selection.');if(checks.length>1&&!confirm(checks.map(c=>c.id+': '+(c.eligible?'construct selected PTM':c.reason)).join('\n')+'\nApply eligible sites as one undoable operation?'))return;await task('Constructing chemical scenario…',async()=>{const previousId=activeId,previousInspection=currentInspection,previousComparison=comparison,created=!currentScenario(),s=currentScenario()??newScenario(),previousEdits=s.edits,previousResult=s.result,previousHistory=structuredClone(history),previousRedo=structuredClone(redo);history.push(structuredClone(s.edits));redo=[];const targetIds=new Set(eligible.map(c=>c.id));s.edits=[...s.edits.filter(e=>!targetIds.has(e.residue)),...eligible.map(c=>({residue:c.id,modification:sel('modification').value}))];try{await refreshScenario();chooseEditForcefield(s.edits);notify('Modification constructed at '+eligible.length+' site(s). Source retained; geometry comparison updated.');}catch(error){s.edits=previousEdits;s.result=previousResult;history=previousHistory;redo=previousRedo;currentInspection=previousInspection;comparison=previousComparison;if(created){scenarios=scenarios.filter(x=>x.id!==s.id);activeId=previousId;}await renderScene();renderScenarios();renderEdits();throw error;}});}

async function applyEditTable(edits:Edit[]){if(!source)throw new Error('Open coordinates first.');if(scenarios.length>=24)throw new Error('The 24-scenario limit has been reached.');const beforeId=activeId,beforeHistory=structuredClone(history),beforeRedo=structuredClone(redo),beforeDirty=dirty;await task('Constructing reviewed edit table…',async()=>{const s=newScenario();s.title='Reviewed chemical edits';history=[[]];s.edits=edits;try{await refreshScenario();chooseEditForcefield(s.edits);}catch(error){scenarios=scenarios.filter(x=>x.id!==s.id);activeId=beforeId;history=beforeHistory;redo=beforeRedo;dirty=beforeDirty;currentInspection=await compute('inspect',{text:currentText(),format:'mmcif'});await renderScene();renderScenarios();renderEdits();updateWorkspaceHeading();throw error;}});}
async function loadSource(next:Source,restore=false){

 if(!restore){assemblyBranches={};molecularTools?.restore(null);sequencePage=0;sequenceRenderKey='';}isolatedIds=null;isolationComponent=null;

 await task('Reading molecular structure…',async()=>{

  const inspection:Inspection=await compute('inspect',{...next,model:0,assembly:'source'});materializedAssembly='source';materializedModel=0;source=next;sourceInspection=inspection;currentInspection=inspection;baselineText=inspection.displayText;

  if(!restore){trajectoryWorkbench?.restore(null);figureStudio?.restore(null);evidenceWorkbench?.restore([]);showTypedInteractions=false;interactionParams=null;contactWorkbench?.restore(null);legacyReports=[];densityMaps=[];notes=[];savedSelections=[];measurementRecords=[];measurementOptions={};labelResidues=[];selectionResidues=[];displayState={};mobileModel=0;scenarios=[];activeId='source';context=null;mobile=null;alignment=null;selectedResidue='';history=[];redo=[];}

  sel('coordinate-model').replaceChildren(...inspection.models.map(m=>option(String(m.index),'Model '+m.name)));sel('assembly').replaceChildren(option('source','Asymmetric unit / supplied model'),...inspection.assemblies.map(a=>option(a.id,'Biological assembly '+a.id)));

  sel('sequence-chain').replaceChildren(...Array.from(new Set(inspection.residues.map(r=>r.chain))).map(c=>option(c,c)));

  text('structure-title',next.name);text('project-name',next.name);text('structure-counts',`${inspection.atoms.length.toLocaleString()} active atoms · ${inspection.residues.length.toLocaleString()} residues`);

  const unp=inspection.crossReferences.find(r=>r.database==='UNP');val('uniprot-id').value=unp?.accession??'';renderScenarios();renderSequence();renderEdits();resetMetrics();renderContext();await renderScene(false);notify('Coordinates opened locally. Select an assembly or residue.');if(!restore)dirty=false;updateWorkspaceHeading();

 });

}

async function switchAssembly(){if(!source)return;const model=Number(sel('coordinate-model').value),assembly=sel('assembly').value;retainAssemblyBranch();try{await task('Building selected assembly…',async()=>{const state:Inspection=await compute('inspect',{...source,model,assembly});const branch=assemblyBranches[branchKey(model,assembly)];materializedAssembly=assembly;materializedModel=model;sourceInspection=state;baselineText=state.displayText;scenarios=branch?.scenarios??[];activeId=branch?.activeId??'source';notes=branch?.notes??[];savedSelections=branch?.savedSelections??[];selectedResidue=branch?.selectedResidue??'';selectionResidues=branch?.selectionResidues??[];measurementRecords=branch?.measurementRecords??[];measurementOptions=branch?.measurementOptions??{};labelResidues=branch?.labelResidues??[];displayState=branch?.displayState??{};history=structuredClone(currentScenario()?.undoHistory??[]);redo=structuredClone(currentScenario()?.redoHistory??[]);currentInspection=currentScenario()?.result?await compute('inspect',{text:currentText(),format:'mmcif',model:0,assembly:'source'}):state;alignment=null;isolatedIds=null;sel('sequence-chain').replaceChildren(...Array.from(new Set(state.residues.map(r=>r.chain))).map(c=>option(c,c)));text('structure-counts',`${state.atoms.length.toLocaleString()} active atoms · ${state.residues.length} residues`);renderScenarios();renderEdits();renderSequence();resetMetrics();renderContext();await renderScene(false);if(currentScenario()?.edits.length)await compare();markDirty();notify(branch?'Model/assembly branch restored with its scenarios.':'Selected assembly built; other scenario branches retained.');});}catch(e){sel('assembly').value=materializedAssembly;sel('coordinate-model').value=String(materializedModel);throw e;}}

function findMapping(r:Residue){

 const pdb=context?.pdb?.toLowerCase();const entries=context?.mapping?.[pdb]?.UniProt??{};const found=[];

 const chain=sourceInspection?.sourceChainMap?.[r.chain]??r.chain;

 for(const [accession,entry] of Object.entries(entries) as any){if(accession!==context.accession)continue;for(const m of entry.mappings??[]){

  const labelSeq=sourceInspection?.residues.find(x=>x.id===r.id)?.labelSeq??r.labelSeq;const start=m.start?.residue_number,end=m.end?.residue_number;if(m.chain_id!==chain||labelSeq===null||labelSeq<start||labelSeq>end)continue;

  const position=m.unp_start+labelSeq-start;if(position>m.unp_end)continue;const covered=sourceInspection?.residues.filter(x=>x.chain===r.chain&&x.kind==='protein'&&x.labelSeq!==null&&x.labelSeq>=start&&x.labelSeq<=end)??[];const mismatches=covered.filter(x=>context.protein.sequence?.value?.[m.unp_start+x.labelSeq!-start-1]?.toUpperCase()!==x.oneLetter.toUpperCase());if(mismatches.length){found.push(`${accession}: ${mismatches.length} resolved residue(s) disagree with the mapped sequence segment; mapping requires review`);continue;}

  const expected=context.protein.sequence?.value?.[position-1];

  if(expected&&expected.toUpperCase()===r.oneLetter.toUpperCase())found.push(`${r.name} ${r.id} ↔ ${accession} residue ${position} · SIFTS segment and residue identity agree`);

  else found.push(`${accession} ${position}: sequence mismatch or unresolved residue; mapping requires review`);

 }}return found.length?found.join(' | '):'No verified mapping between this residue and the retrieved protein.';

}

function renderContext(){const box=$('context-content');box.replaceChildren();if(!context){box.append(node('p','Retrieve context to map this structure to curated protein records.','muted'));return;}const p=context.protein;for(const [title,body]of [['Protein',p.proteinDescription?.recommendedName?.fullName?.value??p.uniProtkbId],['Organism',p.organism?.scientificName],['Gene',p.genes?.map((g:any)=>g.geneName?.value??g.orderedLocusNames?.[0]?.value??'Unnamed gene').join(', ')||'No unique gene assignment supplied'],['Sequence',`${p.sequence?.length??'?'} residues; structural coverage may be partial`]]){const el=node('div',undefined,'context-step');el.append(node('strong',title),node('span',body??'Not recorded'));box.append(el);}

 const refs=p.uniProtKBCrossReferences?.filter((r:any)=>r.database==='Ensembl')??[];const transcripts=node('div',undefined,'context-step');transcripts.append(node('strong','Transcripts / isoforms'));transcripts.append(node('p',refs.length?refs.slice(0,15).map((r:any)=>r.id+(r.isoformId?' · '+r.isoformId:'')).join('\n'):'No transcript cross-reference supplied. A unique transcript cannot be inferred from these coordinates.'));box.append(transcripts);

 for(const t of context.transcripts??[]){const el=node('div',undefined,'context-step');el.append(node('strong',t.id+(t.isoformId?' · '+t.isoformId:'')));if(t.error){el.append(node('p','Transcript details unavailable: '+t.error));box.append(el);continue;}const d=t.detail;el.append(node('p',`Gene ${d.Parent??'unknown'} · ${d.biotype??'transcript'} · strand ${d.strand??'?'} · chromosome ${d.seq_region_name??'?'}`));const exons=d.Exon??[];const track=node('div',undefined,'exon-track');for(const e of exons){const block=node('span');block.title=`${e.id}: ${e.start}–${e.end}`;block.style.flex=String(Math.max(1,e.end-e.start+1));block.setAttribute('aria-label',block.title);track.append(block);}el.append(track,node('small',`${exons.length} exons. Genomic lengths; introns compressed. Structural mapping is shown separately.`));box.append(el);}

 for(const c of p.comments??[]){if(!['ALTERNATIVE PRODUCTS','PTM','FUNCTION','CATALYTIC ACTIVITY','SUBCELLULAR LOCATION'].includes(c.commentType))continue;const el=node('div',undefined,'context-step');el.append(node('strong',c.commentType));if(c.isoforms)for(const iso of c.isoforms)el.append(node('p',`${iso.name?.value??'Isoform'}: ${(iso.isoformIds??[]).join(', ')} · ${(iso.sequenceIds??[]).join(', ')}`));for(const t of c.texts??[])el.append(node('p',t.value));if(c.reaction?.name)el.append(node('p',c.reaction.name));box.append(el);}

 const features=(p.features??[]).filter((f:any)=>['Modified residue','Glycosylation','Signal','Propeptide','Chain','Alternative sequence','Cross-link','Disulfide bond'].includes(f.type));const section=node('div',undefined,'context-step');section.append(node('strong','Processing & sequence features'));for(const f of features.slice(0,70))section.append(node('p',`${f.type}: ${f.location?.start?.value??'?'}–${f.location?.end?.value??'?'} · ${f.description??''}`));box.append(section,node('p',`Source: ${context.source}. Retrieved ${context.retrievedAt}. Evidence and annotation references remain in the saved project.`, 'small muted'));if(context.mappingError)box.append(node('p','Residue mapping unavailable: '+context.mappingError,'muted'));if(selectedResidue){const r=currentInspection?.residues.find(r=>r.id===selectedResidue);if(r)text('feature-track',findMapping(r));}}

function applySettings(settings:any){theme=settings.theme??'midnight';if(!['midnight','glass','pixel'].includes(theme))theme='midnight';document.body.dataset.theme=theme;for(const [id,key,cls]of [['reduced-motion','reducedMotion','reduced-motion'],['reduced-transparency','reducedTransparency','reduced-transparency'],['standard-font','standardFont','standard-font'],['high-contrast','highContrast','high-contrast']]){val(id).checked=settings[key]??id==='reduced-motion';document.body.classList.toggle(cls,val(id).checked);}if(settings.showWater!==undefined)val('show-water').checked=settings.showWater;if(settings.quality)sel('quality').value=settings.quality;if(settings.shortcuts){customShortcuts=settings.shortcuts;for(const input of $('shortcut-editor').querySelectorAll<HTMLInputElement>('input[data-shortcut]'))input.value=customShortcuts[input.dataset.shortcut!]??input.defaultValue;}for(const [id,key,variable]of [['left-width','leftWidth','--left-width'],['right-width','rightWidth','--right-width']]){if(settings[key])val(id).value=String(settings[key]);document.documentElement.style.setProperty(variable,val(id).value+'px');}for(const [id,key]of [['hide-objects','hideObjects'],['hide-inspector','hideInspector']]){if(settings[key]!==undefined)val(id).checked=!!settings[key];document.body.classList.toggle(id,val(id).checked);}if(settings.opacity)val('scene-opacity').value=String(settings.opacity);if(settings.lighting)sel('lighting').value=settings.lighting;if(settings.hiddenTools)hiddenTools=settings.hiddenTools;for(const b of document.querySelectorAll<HTMLElement>('.ribbon [data-command]'))b.hidden=hiddenTools.includes(b.dataset.command!);localStorage.setItem('proteonator.settings',JSON.stringify(currentSettings()));}

