 sel('coordinate-model').onchange=()=>void perform(switchAssembly);sel('assembly').onchange=()=>void perform(switchAssembly);sel('example').onchange=()=>void perform(async()=>{if(dirty&&!confirm('Discard unsaved workspace changes?'))return;await loadSource(await request('example',sel('example').value));});

