 document.addEventListener('keydown',e=>{const editing=(e.target as HTMLElement).matches('input,textarea,select,[contenteditable=true]');if(e.key==='Escape'&&busy&&!document.querySelector('dialog[open]')){void commands.cancel.run();return;}if(editing||document.querySelector('dialog[open]'))return;if(e.key.toLowerCase()==='f'){e.preventDefault();void commands.fit.run();}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();const cam=viewer?.plugin.canvas3d.camera;if(!cam)return;const snap=cam.getSnapshot();const V=window.molstar.lib.math.LinearAlgebra.Vec3;let offset=V.sub(V(),snap.position,snap.target);if(e.key==='+'||e.key==='='||e.key==='-'){V.scale(offset,offset,e.key==='-'?1.15:.87);snap.position=V.add(V(),snap.target,offset);}else if(e.shiftKey){const scale=V.magnitude(offset)*.03,dx=e.key==='ArrowLeft'?-scale:e.key==='ArrowRight'?scale:0,dy=e.key==='ArrowUp'?scale:e.key==='ArrowDown'?-scale:0;snap.position=V.add(V(),snap.position,[dx,dy,0]);snap.target=V.add(V(),snap.target,[dx,dy,0]);}else{const axis=e.key==='ArrowLeft'||e.key==='ArrowRight'?[0,1,0]:[1,0,0],angle=(e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1)*.12;const M=window.molstar.lib.math.LinearAlgebra.Mat4;V.transformMat4(offset,offset,M.fromRotation(M(),angle,axis));snap.position=V.add(V(),snap.target,offset);}cam.setState(snap,0);}});

